import { PlaneGeometry, MeshStandardNodeMaterial, Color, DoubleSide } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ---- Geometry & Material ----
  const geometry = new PlaneGeometry(1.2, 0.4);
  const material = new MeshStandardNodeMaterial({
    color: new Color('#e8ecf2'),
    roughness: 0.5,
    metalness: 0.2,
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 0,
    side: DoubleSide,
    map: null,
  });
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // ---- Texture Loading ----
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    tex.needsUpdate = true;
    material.map = tex;
    material.needsUpdate = true;
  });

  // ---- Handlers ----
  const handlers = {};
  const hoverTimeline = gsap.timeline({ paused: true });
  const clickTimeline = gsap.timeline({ paused: true });
  let isHovered = false;

  handlers.onPointerEnter = () => {
    if (isHovered) return;
    isHovered = true;
    hoverTimeline
      .clear()
      .to(mesh.position, { y: 0.15, duration: 0.4, ease: 'power2.out' }, 0)
      .to(material, { emissiveIntensity: 0.3, duration: 0.3, ease: 'power2.out' }, 0);
  };

  handlers.onPointerLeave = () => {
    if (!isHovered) return;
    isHovered = false;
    hoverTimeline
      .clear()
      .to(mesh.position, { y: 0, duration: 0.4, ease: 'power2.out' }, 0)
      .to(material, { emissiveIntensity: 0, duration: 0.3, ease: 'power2.out' }, 0);
  };

  handlers.onPointerDown = () => {
    clickTimeline
      .clear()
      .to(mesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out' })
      .to(mesh.scale, { x: 1, y: 1, duration: 0.3, ease: 'power4.out' }, '+=0');
    ctx.emit('hub-collection.select', { });
  };

  handlers.onKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      handlers.onPointerDown();
    }
  };

  mesh.userData.handlers = handlers;

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    clickTimeline.kill();
    geometry.dispose();
    material.dispose();
    texturePromise.then((tex) => {
      tex.dispose();
    });
    // Remove event handlers
    delete mesh.userData.handlers;
  };

  // ---- Optional: Contact shadow plane (not needed for small badge) ----
  return group;
}
